    GTCEuStartupEvents.registry('gtceu:material', event => {
        materials.forEach(entry => {
            const builder = event.create('gtcsolo:' + entry.id)
                .color(parseInt(entry.color.substring(1), 16))
                .iconSet(entry.profile === 'fluid' ? GTMaterialIconSet.FLUID : GTMaterialIconSet.METALLIC);
            if (entry.profile !== 'fluid') builder.ingot().dust();
            if (entry.fluid_temperature !== null) {
                builder.liquid(new GTFluidBuilder().temperature(entry.fluid_temperature));
            }
            const flags = profiles[entry.profile].map(name => GTMaterialFlags['GENERATE_' + name]);
            flags.push(GTMaterialFlags.DISABLE_DECOMPOSITION);
            // The authored alloy/refining/sintering routes replace ordinary furnace smelting.
            if (entry.profile !== 'fluid') flags.push(GTMaterialFlags.NO_SMELTING);
            builder.flags(flags);
        });
    });

    GTCEuStartupEvents.materialModification(event => {
        reused.forEach(entry => {
            GTMaterials.get(entry.id).addFlags(entry.flags.map(name => GTMaterialFlags['GENERATE_' + name]));
        });
        const MaterialStack = Java.loadClass('com.gregtechceu.gtceu.api.data.chemical.material.stack.MaterialStack');
        Object.keys(compositions).forEach(name => {
            const material = GTMaterials.get('gtcsolo:' + name);
            material.setComponents(compositions[name].map(component =>
                new MaterialStack(GTMaterials.get(component[0]), component[1])));
            // Alloy grades are not molecular formulae; keep large integer mixing ratios out of item names.
            material.setFormula('');
        });
        const PropertyKey = Java.loadClass('com.gregtechceu.gtceu.api.data.chemical.material.properties.PropertyKey');
        const FluidPipeProperties = Java.loadClass('com.gregtechceu.gtceu.api.data.chemical.material.properties.FluidPipeProperties');
        pipeMaterials.forEach(entry => {
            const material = GTMaterials.get(entry.id);
            const reference = GTMaterials.get(entry.reference).getProperty(PropertyKey.FLUID_PIPE);
            if (!material.hasProperty(PropertyKey.FLUID_PIPE)) {
                material.setProperty(PropertyKey.FLUID_PIPE, new FluidPipeProperties(
                    reference.getMaxFluidTemperature(), reference.getThroughput(), reference.isGasProof(),
                    reference.isAcidProof(), reference.isCryoProof(), reference.isPlasmaProof(), reference.getChannels()));
            }
        });
    });

    // The addon's main tab already includes ordinary forms from every gtcsolo material.
    // Supplement only the native forms missing from its shared prefix list.
    StartupEvents.modifyCreativeTab('gtcsolo:gtcsolo_tab', event => {
        const ChemicalHelper = Java.loadClass('com.gregtechceu.gtceu.api.data.chemical.ChemicalHelper');
        const Prefix = Java.loadClass('com.gregtechceu.gtceu.api.data.tag.TagPrefix');
        const prefixes = [Prefix.dustSmall, Prefix.dustTiny, Prefix.plateDouble, Prefix.wireFine, Prefix.rotor];
        materials.forEach(entry => {
            const material = GTMaterials.get('gtcsolo:' + entry.id);
            prefixes.forEach(prefix => {
                // Three arguments select the material overload unambiguously in Rhino.
                const stack = ChemicalHelper.get(prefix, material, 1);
                if (!stack.isEmpty()) event.add([stack]);
            });
        });
        event.add(['gtcsolo:galinstan_bucket']);
    });
